class Bankkonto
{
    public int Stand { get; private set; }

    public void Einzahlen(int betrag)
    {
        if (betrag <= 0)
            throw new ArgumentException("Betrag muss positiv sein");
        Stand += betrag;
    }

    public void Abheben(int betrag)
    {
        if (betrag <= 0)
            throw new ArgumentException("Betrag muss positiv sein");
        if (betrag > Stand)
            throw new InvalidOperationException("Zu wenig Guthaben");
        Stand -= betrag;
    }
}

