bool Pruefen(string s)
{
    Stapel<char> stapel = new Stapel<char>();
    foreach (char c in s)
    {
        if (c == '(' || c == '[' || c == '{')
        {
            stapel.Push(c);
        }
        else if (c == ')' || c == ']' || c == '}')
        {
            if (stapel.IstLeer)
                return false;
            char offen = stapel.Pop();
            if ((c == ')' && offen != '(') || (c == ']' && offen != '[') || (c == '}' && offen != '{'))
                return false;
        }
    }
    return stapel.IstLeer;
}

class Stapel<T>
{
    private List<T> daten = new List<T>();

    public bool IstLeer { get { return daten.Count == 0; } }

    public void Push(T wert)
    {
        daten.Add(wert);
    }

    public T Peek()
    {
        if (IstLeer)
            throw new InvalidOperationException("Stapel ist leer");
        return daten[daten.Count - 1];
    }

    public T Pop()
    {
        T wert = Peek();
        daten.RemoveAt(daten.Count - 1);
        return wert;
    }
}

