using System.Globalization;

List<Ergebnis> liste = new List<Ergebnis>();
string zeile;
while ((zeile = Console.ReadLine()) != null)
{
    string[] t = zeile.Split(';');
    liste.Add(new Ergebnis(t[0], t[1], int.Parse(t[2])));
}

Ergebnis bester = liste
    .OrderByDescending(e => e.Punkte)
    .ThenBy(e => e.Name, StringComparer.Ordinal)
    .First();
Console.WriteLine($"Bester: {bester.Name} ({bester.Punkte})");

var klassen = liste
    .GroupBy(e => e.Klasse)
    .OrderBy(g => g.Key, StringComparer.Ordinal);
foreach (var g in klassen)
{
    double schnitt = g.Average(e => e.Punkte);
    int bestanden = g.Count(e => e.Punkte >= 50);
    Console.WriteLine($"{g.Key}: Schnitt {schnitt.ToString("0.0", CultureInfo.InvariantCulture)}, bestanden {bestanden}/{g.Count()}");
}

List<string> durchgefallen = liste
    .Where(e => e.Punkte < 50)
    .Select(e => e.Name)
    .OrderBy(n => n, StringComparer.Ordinal)
    .ToList();
Console.WriteLine("Nicht bestanden: " + (durchgefallen.Count == 0 ? "keiner" : string.Join(", ", durchgefallen)));

